"""The WebRTC table the compiler dispatches by, read from rtc.js itself.

A peg's ``await pc.create_offer()`` compiles to
``Workpeg.rtc.call(this, pc, "createOffer", [])``, and rtc.js looks
``"createOffer"`` up again in its own table. There is one table: the JSON
between the two ``/*@rtc-tables*/`` markers of ``runtime/rtc.js``, the file
the build ships. The compiler reads it from there rather than keeping a
copy, so what it writes and what rtc.js accepts cannot drift apart (T-12,
``tests/ui/test_rtc_tables.py``).

It is read only when a module imports from ``workpeg.ui.rtc``: a peg that
does not use the library never opens the file. :func:`tables` reads it once
and keeps it; :func:`load` builds the same thing from any text, which is how
a test hands the compiler rows rtc.js does not have yet.

Every name the compiler writes into a page for a WebRTC construct comes
from here, never from the source text. So the loader refuses a table the
compiler's dispatch could not use safely, and says the install is broken:

- one Python name standing for two browser names, for members or for
  settables. Dispatch is by the Python name alone, with no type inference;
- a member named like a list, string or dict method the compiler already
  dispatches, which would turn ``rows.pop()`` into a WebRTC call, or like
  ``add_event_listener`` and ``remove_event_listener``, which the compiler
  reads before the members, so such a row would never be called;
- a fixed handle whose entry is not a plain name, or is one of the entry
  points (``make``, ``call``, ``on``, ``off``, ``set``). ``media_devices``
  compiles to ``Workpeg.rtc.<entry>``, the one table string written as code
  rather than inside a string literal, and an entry point is a function.
"""
from __future__ import annotations

import json
import keyword
import re
from dataclasses import dataclass
from pathlib import Path
from types import MappingProxyType
from typing import Any, Mapping

#: The file the build ships, beside the bundled runtime: the same path
#: build.py reads its runtime files from.
RTC_JS = Path(__file__).parent.parent / "runtime" / "rtc.js"

#: What the table sits between, twice.
MARKER = "/*@rtc-tables*/"

#: The functions rtc.js installs on ``Workpeg.rtc``. Every other entry is a
#: fixed handle, which holds no function.
ENTRY_POINTS = frozenset(("make", "call", "on", "off", "set"))

#: The Python names a peg listens with, and the entry each compiles to. The
#: compiler reads them before the member table, so no row may take one.
LISTENERS = MappingProxyType({"add_event_listener": "on",
                              "remove_event_listener": "off"})

# A fixed handle's entry is written as ``Workpeg.rtc.<entry>``.
_ENTRY = re.compile(r"[a-z][A-Za-z0-9]*\Z")


class RtcTableError(RuntimeError):
    """rtc.js's table is missing, unreadable, or breaks a rule the compiler
    relies on. It is the SDK's file, so this is never the peg's fault."""


@dataclass(frozen=True)
class Construct:
    """A kind a peg makes: ``RTCPeerConnection(...)``."""
    kind: str
    browser: str
    #: The positional argument rows, in order.
    args: tuple
    #: The Python keyword names.
    keywords: tuple
    row: Mapping[str, Any]


@dataclass(frozen=True)
class Member:
    """A method of a kind: ``pc.create_offer()`` is ``createOffer``."""
    kind: str
    python: str
    browser: str
    is_async: bool
    #: The positional argument rows, in order.
    args: tuple
    #: The row each further argument is checked by, with its ``max``.
    rest: "Mapping[str, Any] | None"
    row: Mapping[str, Any]


@dataclass(frozen=True)
class Settable:
    """A property a peg may assign: ``track.enabled = False``."""
    kind: str
    python: str
    browser: str
    row: Mapping[str, Any]


@dataclass(frozen=True)
class Fixed:
    """A handle the page never makes: ``media_devices``."""
    kind: str
    python: str
    entry: str

    @property
    def js(self) -> str:
        return f"Workpeg.rtc.{self.entry}"


@dataclass(frozen=True)
class Tables:
    kinds: frozenset
    #: By kind, for the kinds a peg constructs.
    constructed: Mapping[str, Construct]
    #: By Python name: ``media_devices``, ``signaling``.
    fixed: Mapping[str, Fixed]
    #: By Python name, the rows of every kind that has one. They share one
    #: browser name.
    members: Mapping[str, tuple]
    #: By kind, then by Python name.
    kind_members: Mapping[str, Mapping[str, Member]]
    #: By Python name, the rows of every kind that has one, one browser name.
    settables: Mapping[str, tuple]
    #: By kind, the event names it fires.
    events: Mapping[str, frozenset]
    all_events: frozenset
    #: By kind, Python name to browser name.
    getters: Mapping[str, Mapping[str, str]]
    #: What ``from workpeg.ui.rtc import ...`` may name: every kind, and
    #: the fixed handles' Python names.
    names: frozenset
    raw: Mapping[str, Any]


_cache: "Tables | None" = None


def _read() -> str:
    """rtc.js's text. The one place the compiler opens the file."""
    try:
        return RTC_JS.read_text(encoding="utf-8")
    except OSError as e:
        raise _broken(f"it cannot be read ({e.strerror or e})") from e


def tables() -> Tables:
    """The table, read from rtc.js the first time it is asked for."""
    global _cache
    if _cache is None:
        _cache = load(_read())
    return _cache


def _broken(why: str) -> RtcTableError:
    return RtcTableError(
        f"The WebRTC table in workpeg's rtc.js is unusable: {why}. That file "
        "is part of the SDK, so the install is broken, not your peg: "
        "reinstall workpeg.")


def _dict(value: Any, where: str) -> dict:
    if not isinstance(value, dict):
        raise _broken(f"{where} is not an object")
    return value


def _python_name(name: Any, where: str) -> str:
    if (not isinstance(name, str) or not name.isidentifier()
            or keyword.iskeyword(name) or name.startswith("_")):
        raise _broken(f"{where} has no usable Python name ({name!r})")
    return name


def _rows(value: Any, where: str) -> tuple:
    if not isinstance(value, list) or not all(isinstance(r, dict) for r in value):
        raise _broken(f"{where} is not a list of rows")
    return tuple(MappingProxyType(r) for r in value)


def _one_browser_name(found: dict, what: str) -> None:
    for python, browsers in sorted(found.items()):
        if len(browsers) > 1:
            names = " and ".join(sorted(browsers))
            raise _broken(
                f"the {what} '{python}' stands for two browser names, {names}. "
                "The compiler picks the browser name by the Python name "
                "alone, so one Python name is one browser name")


def _not_a_collection_method(members: Mapping[str, tuple]) -> None:
    # Imported here: the parser imports this module.
    from workpeg.ui.compiler.ast_parser import (
        _DICT_VALUE_METHODS, _LIST_MUTATOR_METHODS, _LIST_VALUE_METHODS)
    taken = _LIST_VALUE_METHODS | _LIST_MUTATOR_METHODS | _DICT_VALUE_METHODS
    for python in sorted(set(members) & taken):
        kinds = ", ".join(sorted(m.kind for m in members[python]))
        raise _broken(
            f"the member '{python}' of {kinds} is also a list, string or dict "
            f"method the compiler dispatches, so x.{python}() would mean two "
            "things")


def load(text: str) -> Tables:
    """The table in ``text``, the whole of an rtc.js, checked."""
    parts = text.split(MARKER) if isinstance(text, str) else []
    if len(parts) != 3:
        raise _broken(
            f"its table should sit between two {MARKER} markers, and there "
            f"are {max(len(parts) - 1, 0)}")
    try:
        raw = json.loads(parts[1])
    except ValueError as e:
        raise _broken(f"its table is not JSON ({e})") from e
    kinds = _dict(_dict(raw, "the table").get("kinds"), "the table's kinds")
    if not kinds:
        raise _broken("its table names no kinds")

    constructed: dict = {}
    fixed: dict = {}
    members: dict = {}
    kind_members: dict = {}
    settables: dict = {}
    events: dict = {}
    getters: dict = {}
    member_browsers: dict = {}
    settable_browsers: dict = {}

    for kind, spec in kinds.items():
        _python_name(kind, f"the kind {kind!r}")
        spec = _dict(spec, f"the kind {kind}")
        for field in ("members", "events", "settables", "getters"):
            _dict(spec.get(field), f"{kind}.{field}")

        if "construct" in spec:
            row = _dict(spec["construct"], f"{kind}.construct")
            keywords = _dict(row.get("keywords"), f"{kind}.construct.keywords")
            constructed[kind] = Construct(
                kind=kind, browser=row.get("browser"),
                args=_rows(row.get("args"), f"{kind}.construct.args"),
                keywords=tuple(_python_name(k, f"{kind}.construct.keywords")
                               for k in keywords),
                row=MappingProxyType(row))

        if "fixed" in spec or "python" in spec:
            entry = spec.get("fixed")
            if not isinstance(entry, str) or not _ENTRY.match(entry) \
                    or entry in ENTRY_POINTS:
                raise _broken(
                    f"the fixed handle {kind} has the entry {entry!r}: it is "
                    "written as Workpeg.rtc.<entry>, so it must be a plain "
                    f"name and not one of {', '.join(sorted(ENTRY_POINTS))}")
            if "construct" in spec:
                raise _broken(f"the fixed handle {kind} is also constructed")
            python = _python_name(spec.get("python"), f"the fixed handle {kind}")
            if python in kinds or python in fixed:
                raise _broken(
                    f"the fixed handle {kind} takes the name '{python}', "
                    "which another kind or fixed handle already has")
            if entry in {f.entry for f in fixed.values()}:
                raise _broken(
                    f"the fixed handle {kind} shares the entry '{entry}'")
            fixed[python] = Fixed(kind=kind, python=python, entry=entry)

        rows: dict = {}
        for browser, row in spec["members"].items():
            where = f"{kind}.members.{browser}"
            row = _dict(row, where)
            python = _python_name(row.get("python"), where)
            rest = row.get("rest")
            member = Member(
                kind=kind, python=python, browser=browser,
                is_async=row.get("async") is True,
                args=_rows(row.get("args"), f"{where}.args"),
                rest=MappingProxyType(_dict(rest, f"{where}.rest"))
                if rest is not None else None,
                row=MappingProxyType(row))
            rows[python] = member
            members.setdefault(python, []).append(member)
            member_browsers.setdefault(python, set()).add(browser)
        kind_members[kind] = MappingProxyType(rows)

        for browser, row in spec["settables"].items():
            where = f"{kind}.settables.{browser}"
            row = _dict(row, where)
            python = _python_name(row.get("python"), where)
            settables.setdefault(python, []).append(Settable(
                kind=kind, python=python, browser=browser,
                row=MappingProxyType(row)))
            settable_browsers.setdefault(python, set()).add(browser)

        events[kind] = frozenset(spec["events"])
        named = {}
        for python, row in spec["getters"].items():
            where = f"{kind}.getters.{python}"
            browser = _dict(row, where).get("browser")
            if not isinstance(browser, str):
                raise _broken(f"{where} names no browser property")
            named[_python_name(python, where)] = browser
        getters[kind] = MappingProxyType(named)

    _one_browser_name(member_browsers, "member")
    _one_browser_name(settable_browsers, "settable")
    members = {p: tuple(rows) for p, rows in members.items()}
    _not_a_collection_method(members)
    for python in sorted(set(members) & set(LISTENERS)):
        raise _broken(
            f"the member '{python}' of "
            f"{', '.join(sorted(m.kind for m in members[python]))} takes the "
            "name a peg listens for an event with, which the compiler reads "
            "first, so the row would never be called")

    return Tables(
        kinds=frozenset(kinds),
        constructed=MappingProxyType(constructed),
        fixed=MappingProxyType(fixed),
        members=MappingProxyType(members),
        kind_members=MappingProxyType(kind_members),
        settables=MappingProxyType(
            {p: tuple(rows) for p, rows in settables.items()}),
        events=MappingProxyType(events),
        all_events=frozenset().union(*events.values()),
        getters=MappingProxyType(getters),
        names=frozenset(kinds) | frozenset(fixed),
        raw=MappingProxyType(raw),
    )
